#!/usr/bin/env node
import { Command } from "commander";
import pc from "picocolors";

import { greet } from "./greet.js";

const program = new Command()
  .name("{{name}}")
  .description("What {{name}} does, in one line.")
  .version("0.1.0");

program
  .command("hello")
  .description("Say hello")
  .argument("[name]", "who to greet", "world")
  .option("-l, --loud", "shout it")
  .action((name: string, options: { loud?: boolean }) => {
    console.log(pc.green(greet(name, options)));
  });

program.parseAsync().catch((error: unknown) => {
  console.error(pc.red(error instanceof Error ? error.message : String(error)));
  process.exit(1);
});

/** Pure logic lives apart from the commands, so it can be tested without spawning the CLI. */
export function greet(name: string, options: { loud?: boolean } = {}): string {
  const message = `Hello, ${name}!`;
  return options.loud ? message.toUpperCase() : message;
}

import { describe, expect, it } from "vitest";

import { greet } from "./greet.js";

describe("greet", () => {
  it("greets by name", () => {
    expect(greet("Ada")).toBe("Hello, Ada!");
  });

  it("shouts with --loud", () => {
    expect(greet("Ada", { loud: true })).toBe("HELLO, ADA!");
  });
});
